import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
fs={
 'tlog_p': lambda p: p[3]*t*np.log(p[4]+t),
 'tlog_lin': lambda p: p[3]*t*np.log(1+p[4]*t)+p[5]*t,
 'tlog_sqrtt': lambda p: p[3]*t*np.log(1+p[4]*t**2),
 'tlog_pow': lambda p: p[3]*t*np.log(1+p[4]*t)**p[5],
 'tlog_x': lambda p: p[3]*t*np.log1p(p[4]*t)/(1+p[5]*t),
}
for n,g in fs.items():
    best=None
    rng=np.random.default_rng(0)
    for i in range(12):
        st=np.concatenate([[3.7,0.173,0.094,-0.18],rng.uniform(0.3,3,2)])
        if n=='tlog_lin': st=np.concatenate([[3.7,0.173,0.094,-0.18,rng.uniform(0.3,3),0.0]])
        if n=='tlog_pow': st=np.concatenate([[3.7,0.173,0.094,-0.18,rng.uniform(0.3,3),1.0]])
        if n=='tlog_x': st=np.concatenate([[3.7,0.173,0.094,-0.18,rng.uniform(0.3,3),0.1]])
        try:
            s=least_squares(lambda p: p[0]*np.sqrt(t)+p[1]*np.exp(-p[2]*t)*A**3+g(p)-y, st, max_nfev=4000)
